import type {
  MultiSelectProps,
  MultiSelectContextType,
  MultiSelectOption,
  AnnouncementFormatter,
} from "../multi-select.types";

import {
  useState,
  useCallback,
  useEffect,
  useRef,
  useId,
  createContext,
  useContext,
  useMemo,
} from "react";
import { useIsomorphicLayoutEffect } from "@system";

const defaultAnnouncementFormatter: AnnouncementFormatter = ({
  option,
  index,
  total,
  isSelected,
  isSelectAll,
}) => {
  if (isSelectAll) {
    const selected = isSelected ? "selected" : "not selected";
    return `Select All, ${selected}`;
  }
  const selected = isSelected ? "selected" : "not selected";
  return `${option!.label}, ${selected}, ${index + 1} of ${total}`;
};

export const useMultiSelectState = ({
  value: valueProp,
  defaultValue = [],
  onValueChange,
  defaultOpen = false,
  onOpenChange,
  options = [],
  deduplicateOptions,
  sortSelectedFirst = true,
  sort,
  announcementFormatter = defaultAnnouncementFormatter,
}: MultiSelectProps) => {
  // region State
  const [open, setOpen] = useState(defaultOpen);
  const [triggerWidth, setTriggerWidth] = useState<number | null>(null);
  const [focusedValue, setFocusedValue] = useState<string | null>(null);
  const [hasSelectAll, setHasSelectAll] = useState(false);
  const [hasSearch, setHasSearch] = useState(false);
  const [sortedOptions, setSortedOptions] = useState<MultiSelectOption[]>([]);
  const [searchValue, setSearchValue] = useState("");
  const isControlled = valueProp !== undefined;
  const [internalValue, setInternalValue] = useState(defaultValue);
  const value = isControlled ? valueProp : internalValue;
  const [pendingValue, setPendingValue] = useState(value);
  const [isOpening, setIsOpening] = useState(false);
  const [isFiltering, setIsFiltering] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  // endregion

  // region Refs
  const triggerRef = useRef<HTMLButtonElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const prevValueRef = useRef(value);
  const isOutsideClick = useRef(false);
  // endregion

  // region Memoized Values
  const contentId = useId();

  const filteredOptions = useMemo(() => {
    if (!searchValue) return sortedOptions;
    return sortedOptions.filter(
      (option) =>
        option.label.toLowerCase().includes(searchValue.toLowerCase()) ||
        option.value.toLowerCase().includes(searchValue.toLowerCase()),
    );
  }, [sortedOptions, searchValue]);

  const isAllSelected = useMemo((): boolean | "indeterminate" => {
    const allFilteredValues = filteredOptions.filter((o) => !o.disabled).map((o) => o.value);
    if (allFilteredValues.length === 0) return false;
    if (pendingValue.length === allFilteredValues.length) return true;
    if (pendingValue.length > 0) return "indeterminate";
    return false;
  }, [pendingValue, filteredOptions]);
  // endregion

  // In-render state updates
  if (prevValueRef.current !== value) {
    setPendingValue(value);
    prevValueRef.current = value;
  }

  // region Callbacks
  const getAllOptions = useCallback((): MultiSelectOption[] => {
    if (!deduplicateOptions) {
      return options as MultiSelectOption[];
    }

    const uniqueOptions: MultiSelectOption[] = [];
    const valueSet = new Set<string>();

    for (const option of options) {
      if (!valueSet.has(option.value)) {
        valueSet.add(option.value);
        uniqueOptions.push(option as MultiSelectOption);
      }
    }

    return uniqueOptions;
  }, [options, deduplicateOptions]);

  const handleOpenChange = useCallback(
    (newOpen: boolean) => {
      if (newOpen) {
        setIsOpening(true);
      }
      setOpen(newOpen);
      onOpenChange?.(newOpen);
      if (!newOpen) {
        setSearchValue("");
        setFocusedValue(null);
        setPendingValue(value);
      }
    },
    [onOpenChange, value],
  );

  const handleValueChange = useCallback(
    (newValue: string[]) => {
      if (onValueChange) {
        onValueChange(newValue);
      }
      if (!isControlled) {
        setInternalValue(newValue);
      }
    },
    [isControlled, onValueChange],
  );

  const handleSingleValueChange = useCallback(
    (itemValue: string) => {
      const option = getAllOptions().find((opt) => opt.value === itemValue);
      if (!option || option.disabled) return;

      const isSelected = pendingValue.includes(itemValue);
      const newValue = isSelected
        ? pendingValue.filter((v) => v !== itemValue)
        : [...pendingValue, itemValue];
      setPendingValue(newValue);

      handleValueChange(newValue);
    },
    [pendingValue, handleValueChange, getAllOptions],
  );

  const applySelections = useCallback(() => {
    handleValueChange(pendingValue);
    handleOpenChange(false);
  }, [pendingValue, handleValueChange, handleOpenChange]);

  const handleSelectAll = useCallback(
    (e: Event | React.SyntheticEvent<HTMLElement, Event>) => {
      e.preventDefault?.();
      const allFilteredValues = filteredOptions.filter((o) => !o.disabled).map((o) => o.value);
      const newValue = isAllSelected === true ? [] : allFilteredValues;

      setPendingValue(newValue);
      handleValueChange(newValue);
    },
    [isAllSelected, filteredOptions, handleValueChange],
  );

  const clearValue = useCallback(() => {
    handleValueChange([]);
  }, [handleValueChange]);
  // endregion

  // region Effects
  useIsomorphicLayoutEffect(() => {
    if (open) {
      const allOptions = getAllOptions();
      const sorted = [...allOptions];

      if (sort) {
        sorted.sort(sort);
      }

      if (sortSelectedFirst) {
        sorted.sort((a, b) => {
          const aIsSelected = value.includes(a.value);
          const bIsSelected = value.includes(b.value);
          if (aIsSelected && !bIsSelected) return -1;
          if (!aIsSelected && bIsSelected) return 1;
          return 0;
        });
      }

      if (JSON.stringify(sorted) !== JSON.stringify(sortedOptions)) {
        setSortedOptions(sorted);
      }

      if (hasSearch) {
        searchRef.current?.focus();
      }

      if (hasSelectAll) {
        setFocusedValue("select-all");
      } else if (sorted.length > 0) {
        setFocusedValue(sorted[0]?.value);
      } else {
        setFocusedValue(null);
      }
    }
  }, [open, hasSelectAll, getAllOptions, sortSelectedFirst, sort, hasSearch, sortedOptions]);

  useEffect(() => {
    if (open) {
      setIsOpening(false);
    }
  }, [open]);

  // endregion

  // region Keyboard Navigation
  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const selectAllItem = hasSelectAll ? ["select-all"] : [];
    const allItems = [...selectAllItem, ...filteredOptions.map((o) => o.value)];

    const handleNavigation = (direction: "down" | "up" | "home" | "end") => {
      e.preventDefault();
      let currentIndex = -1;
      if (focusedValue) {
        const idx = allItems.indexOf(focusedValue);
        if (idx !== -1) {
          currentIndex = idx;
        }
      }

      let nextIndex;
      if (direction === "home") {
        nextIndex = 0;
      } else if (direction === "end") {
        nextIndex = allItems.length - 1;
      } else if (direction === "down") {
        nextIndex = (currentIndex + 1) % allItems.length;
      } else {
        nextIndex = (currentIndex - 1 + allItems.length) % allItems.length;
      }

      const nextFocusedValue = allItems[nextIndex];
      const isSelectAll = nextFocusedValue === "select-all";

      if (isSelectAll) {
        setFocusedValue("select-all");
      } else {
        setFocusedValue(nextFocusedValue);
      }
    };

    const handleSelection = () => {
      if (focusedValue === "select-all") {
        handleSelectAll({} as React.SyntheticEvent<HTMLElement, Event>);
      } else if (focusedValue) {
        handleSingleValueChange(focusedValue);
      }
    };

    switch (e.key) {
      case "ArrowDown":
        handleNavigation("down");
        break;
      case "ArrowUp":
        handleNavigation("up");
        break;
      case "Enter":
      case " ": // Space key
        e.preventDefault();
        handleSelection();
        break;
      case "Escape":
        e.preventDefault();
        handleOpenChange(false);
        break;
      case "Home":
        handleNavigation("home");
        break;
      case "End":
        handleNavigation("end");
        break;
      case "ArrowLeft":
      case "ArrowRight":
      default:
        break;
    }
  };
  // endregion

  return {
    value,
    onValueChange: handleValueChange,
    handleKeyDown,
    onSingleValueChange: handleSingleValueChange,
    open,
    setOpen: handleOpenChange,
    applySelections,
    pendingValue,
    triggerWidth,
    setTriggerWidth,
    focusedValue,
    setFocusedValue,
    triggerRef,
    searchRef,
    contentId,
    contentRef,
    options: options,
    allOptions: getAllOptions(),
    searchValue,
    setSearchValue,
    activeDescendant:
      open && !isOpening && focusedValue && !isFiltering
        ? `${contentId}-${focusedValue}`
        : undefined,
    filteredOptions,
    isOpening,
    setIsOpening,
    isAllSelected,
    handleSelectAll,
    hasSelectAll,
    setHasSelectAll,
    hasSearch,
    setHasSearch,
    setIsFiltering,
    announcementFormatter,
    clearValue,
    announcement,
    setAnnouncement,
    sortedOptions,
    isOutsideClick,
  };
};

export const MultiSelectContext = createContext<MultiSelectContextType | null>(null);

export const useMultiSelect = () => {
  const context = useContext(MultiSelectContext);
  if (!context) {
    throw new Error("useMultiSelect must be used within a MultiSelect");
  }
  return context;
};
